<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount} from 'vue';
import Modal from '../work/Modal.vue';
import {WORK_STATUSES,workUserName,type WorkTaskDTO,type WorkUser} from '~~/shared/types/work';
import {UPTS_CONTRACT_TYPES} from '~~/shared/types/upts-library';
import {formatWorkDate} from '~~/shared/utils/work-board';
import type {UptsContractDTO,UptsProjectDTO} from '~~/shared/types/upts';
const props=defineProps<{contractId:number}>();
const emit=defineEmits<{close:[];changed:[];work:[task:WorkTaskDTO];edit:[object:UptsContractDTO];files:[project:UptsProjectDTO,contractId:number]}>();
const data=ref<{object:UptsContractDTO;project:UptsProjectDTO;canAssign:boolean;tasks:(WorkTaskDTO&{fileCount:number})[];notifications:{taskId:number;emailSentAt:string|null;chatSentAt:string|null;lastError:string|null}[]}|null>(null),people=ref<WorkUser[]>([]),error=ref(''),busy=ref(false),selected=ref<number[]>([]),assignee=ref<number|null>(null),anchor=ref(0),drag=ref<number|null>(null);
const d=computed(()=>data.value?.object.objectDetails||{});
const rows=computed(()=>data.value?.tasks||[]);
const selectable=computed(()=>rows.value.filter(t=>!['DONE','CANCELLED'].includes(t.status)));
const statusName=(status:string)=>(WORK_STATUSES as Record<string,string>)[status]||status;
const stats=computed(()=>({all:rows.value.length,todo:rows.value.filter(t=>t.status==='TODO').length,active:rows.value.filter(t=>t.status==='IN_PROGRESS').length,review:rows.value.filter(t=>t.status==='REVIEW').length,done:rows.value.filter(t=>t.status==='DONE').length}));
const characteristics=computed(()=>[['Условный номер',data.value?.object.number],['Кадастровый номер',d.value.sourceCadastralNumber],['Объект',d.value.road],['Тип',data.value?.object.contractType?UPTS_CONTRACT_TYPES[data.value.object.contractType]:''],['Местоположение',d.value.address],['Площадь, кв. м',d.value.sourceArea],['Категория земель',d.value.landCategory],['ВРИ',d.value.permittedUses?.join('; ')],['Вид права',d.value.rightKind],['Правообладатель',d.value.rightHolders?.join('; ')],['Номер договора',d.value.basisContractNumber],['Дата договора',formatWorkDate(d.value.basisContractDate)],['Номер заявки',d.value.requestNumber],['Начало работ',formatWorkDate(d.value.workStartDate)],['Окончание работ',formatWorkDate(data.value?.object.dueDate)],['Куратор',person(d.value.curatorId)],['Кадастровый инженер',person(d.value.engineerId)],['Количество этапов',d.value.stageCount||1],['Этап строительства',d.value.stage],['Область',d.value.region],['Тип сделки',d.value.dealType],['Тип учёта',d.value.accountingType],['КУВД',d.value.kuvdEntries?.map(k=>[k.number,formatWorkDate(k.date)].filter(Boolean).join(' · ')).join('; ')],['Комментарий',d.value.otherDescription]]);
function person(id?:number|null){return id?workUserName(people.value.find(p=>p.id===id)||{id,fullName:null,login:null}):'—';}
async function load(){busy.value=true;error.value='';try{const [v,p]=await Promise.all([$fetch<NonNullable<typeof data.value>>(`/api/upts/contracts/${props.contractId}/overview`),$fetch<WorkUser[]>('/api/upts/people')]);data.value=v;people.value=p;selected.value=[];}catch(e:any){error.value=e.data?.message||'Не удалось загрузить карточку объекта.';}finally{busy.value=false;}}
function choose(index:number,shift=false){if(busy.value||!data.value?.canAssign)return;if(!shift)anchor.value=index;selected.value=rows.value.slice(Math.min(anchor.value,index),Math.max(anchor.value,index)+1).filter(t=>!['DONE','CANCELLED'].includes(t.status)).map(t=>t.id);}
function begin(e:PointerEvent,i:number){if(e.button!==0||(e.target as HTMLElement).closest('input,button,select'))return;choose(i,e.shiftKey);drag.value=e.shiftKey?anchor.value:i;e.preventDefault();}
function enter(e:PointerEvent,i:number){if(drag.value===null)return;if(!(e.buttons&1)){drag.value=null;return;}anchor.value=drag.value;choose(i,true);}
async function assign(){if(!assignee.value||!selected.value.length)return;busy.value=true;error.value='';try{await $fetch(`/api/upts/contracts/${props.contractId}/assign`,{method:'POST',headers:{'x-space-work':'1'},body:{assigneeId:assignee.value,tasks:rows.value.filter(t=>selected.value.includes(t.id)).map(t=>({id:t.id,version:t.version}))}});await load();emit('changed');}catch(e:any){error.value=e.data?.message||'Не удалось назначить исполнителя. Обновите карточку.';}finally{busy.value=false;}}
function endDrag(){drag.value=null;}
onMounted(()=>{load();window.addEventListener('pointerup',endDrag);window.addEventListener('blur',endDrag);});
onBeforeUnmount(()=>{window.removeEventListener('pointerup',endDrag);window.removeEventListener('blur',endDrag);});
</script>
<template><Modal full-height wide icon="streamline-kameleon-color:map-pin" title="Карточка объекта" @close="emit('close')">
 <p v-if="error" class="work-error" role="alert">{{ error }}</p><button :disabled="busy" @click="load">Обновить</button>
 <template v-if="data"><div class="object-overview-fields"><div v-for="([label,value],i) in characteristics" :key="i"><small>{{ label }}</small><p>{{ value || '—' }}</p></div></div>
 <div class="work-actions"><button v-if="data.project.canManage&&!data.project.archivedAt" @click="emit('edit',data.object)">Редактировать объект</button><button @click="emit('files',data.project,data.object.id)">Документы объекта</button></div>
 <div class="object-overview-stats"><span>Всего: {{ stats.all }}</span><span>Запланировано: {{ stats.todo }}</span><span>В работе: {{ stats.active }}</span><span>На проверке: {{ stats.review }}</span><span>Выполнено: {{ stats.done }}</span></div>
 <div v-if="data.canAssign" class="work-toolbar"><span>Выделено: {{ selected.length }}</span><label>Исполнитель<select v-model="assignee" :disabled="busy"><option :value="null">Выберите сотрудника</option><option v-for="p in people" :key="p.id" :value="p.id">{{ workUserName(p) }}</option></select></label><button :disabled="busy||!assignee||!selected.length" @click="assign">Назначить выделенным</button></div>
 <p v-if="data.canAssign" class="work-muted">Выделите строки флажками, Shift-кликом или перетягиванием. Завершённые работы не переназначаются.</p>
 <div class="work-table-wrap"><table class="object-work-table"><thead><tr><th v-if="data.canAssign"><input type="checkbox" aria-label="Выделить все работы" :checked="!!selectable.length&&selected.length===selectable.length" @change="selected=($event.target as HTMLInputElement).checked?selectable.map(t=>t.id):[]" /></th><th>№</th><th>Работа</th><th>Этап</th><th>Статус</th><th>Исполнитель</th><th>Начало (план)</th><th>Срок</th><th>Начало (факт)</th><th>Завершено</th><th>Результат</th><th>Файлы</th></tr></thead><tbody><tr v-for="(t,i) in rows" :key="t.id" :class="{selected:selected.includes(t.id)}" @pointerdown="begin($event,i)" @pointerenter="enter($event,i)" @pointerup="drag=null" @dblclick="emit('work',t)"><td v-if="data.canAssign"><input v-model="selected" :disabled="busy || t.status==='DONE' || t.status==='CANCELLED'" type="checkbox" :value="t.id" :aria-label="'Выделить '+t.title" /></td><td>{{ i+1 }}</td><td><button @click="emit('work',t)">{{ t.title }}</button></td><td>{{ t.uptsWorkMeta?.stageNumber||1 }}</td><td>{{ statusName(t.status) }}</td><td>{{ t.assignee?workUserName(t.assignee):'Не назначен' }}</td><td>{{ formatWorkDate(t.startDate)||'—' }}</td><td>{{ formatWorkDate(t.dueDate)||'—' }}</td><td>{{ formatWorkDate(t.uptsWorkMeta?.startedAt)||'—' }}</td><td>{{ formatWorkDate(t.uptsWorkMeta?.completedAt)||'—' }}</td><td>{{ t.uptsWorkMeta?.resultText||'—' }}</td><td>{{ t.fileCount }}</td></tr></tbody></table></div>
 <details v-if="data.canAssign&&data.notifications.length"><summary>Доставка уведомлений</summary><p v-for="(n,i) in data.notifications" :key="i">Работа #{{ n.taskId }} · чат: {{ n.chatSentAt?'доставлено':'в очереди' }} · email: {{ n.emailSentAt?'отправлено':'в очереди' }} {{ n.lastError||'' }}</p></details>
 </template>
</Modal></template>
<style scoped>
.object-overview-fields{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;padding:16px 0}.object-overview-fields small{color:var(--work-muted)}.object-overview-fields p{margin:3px 0;overflow-wrap:anywhere}.object-overview-stats{display:flex;flex-wrap:wrap;gap:18px;padding:16px 0;font-weight:600}.object-work-table{min-width:1150px}.object-work-table :is(th,td){padding:5px 8px;font-size:12px}.object-work-table tr{user-select:none}.object-work-table tr.selected{background:color-mix(in srgb,var(--work-accent) 18%,var(--work-panel))}.object-work-table td button{border:0;padding:0;background:transparent;color:var(--work-accent)}@media(max-width:700px){.object-overview-fields{grid-template-columns:repeat(2,minmax(0,1fr))}}
</style>
